mapper.select:
SELECT lr.id AS id, lr.anchor_name AS name, lr.anchor_avatar AS anchorAvatar, COALESCE(SUM(sp.view_count), 0) AS viewCount, COALESCE(SUM(sp.sales_revenue), 0) AS salesRevenue, COALESCE(SUM(sp.refund), 0) AS refund, COALESCE(SUM(sp.net_sales), 0) AS netSales, COALESCE(SUM(sp.investment), 0) AS investment FROM live_room lr LEFT JOIN session_performance sp ON sp.live_room_id = lr.id AND sp.tenant_id = #{req.tenantId} AND sp.stats_date BETWEEN #{req.startDate} AND #{req.endDate} AND sp.is_deleted = 0 WHERE lr.tenant_id = #{req.tenantId} AND lr.is_deleted = 0
AND lr.company_id = #{req.companyId}
AND lr.dept_id = #{req.deptId}
AND lr.team_id = #{req.teamId}
AND lr.id IN
#{id}
AND lr.anchor_name LIKE CONCAT('%', #{req.name}, '%')
GROUP BY lr.id ORDER BY
viewCount salesRevenue refund netSales investment salesRevenue
ASC DESC
